mapper.select:
SELECT P.PYMNT_REQ_NO , P.REF_NO AS CNTRCT_NO , P.DMINSTT_CD , P.BIZRNO , P.REQ_YMD , P.REQ_AMT , P.PYMNT_STTS_CD , C.CD_NM AS PYMNT_STTS_NM , P.PYMNT_YMD , P.BDGT_ACNT_NM FROM TB_PYMNT P LEFT OUTER JOIN TB_CMMN_CD C ON C.CD_ID = 'PYMNT_STTS' AND C.CD = P.PYMNT_STTS_CD WHERE 1 = 1
AND P.PYMNT_REQ_NO = #{pymntReqNo}
AND P.REF_NO = #{refNo}

SELECT P.PYMNT_REQ_NO , P.REF_NO AS CNTRCT_NO , P.REQ_YMD , P.REQ_AMT , P.PYMNT_STTS_CD , C.CD_NM AS PYMNT_STTS_NM FROM TB_PYMNT P LEFT OUTER JOIN TB_CMMN_CD C ON C.CD_ID = 'PYMNT_STTS' AND C.CD = P.PYMNT_STTS_CD WHERE 1 = 1
AND P.DMINSTT_CD = #{dminsttCd}
AND P.PYMNT_STTS_CD = #{pymntSttsCd}
ORDER BY P.REQ_YMD DESC
